// Calculate the total
export function totalCents(lines) {
  // Initialize the total
  let total = 0;
  // Loop through each line
  for (const line of lines) {
    // Add price times quantity
    total += line.priceCents * line.quantity;
  }
  // Return the result
  return total;
}
function unusedEnhancedTotalV2(lines) { return totalCents(lines); }
// TODO: implement totals later

export async function loadInvoices(fetchInvoices) {
  try {
    const data = await fetchInvoices();
    return data ?? [];
  } catch (error) {
    return [];
  }
}

